import android.app.*;
import android.os.*;
import android.content.*;
import android.content.pm.PackageManager;
import android.graphics.*;
import android.graphics.drawable.GradientDrawable;
import android.view.*;
import android.widget.*;
import java.util.*;
import java.text.SimpleDateFormat;

public class MainActivity extends Activity {
    static final int BG=0xff080b12, PANEL=0xff141a24, PANEL2=0xff1b2431, TEXT=0xfff4f6fb, MUTED=0xff8d99aa, GREEN=0xff83e2b2, BLUE=0xff91b9ff, ORANGE=0xffffbd75, RED=0xffff777d;
    LinearLayout root, content, nav;
    TextView pct,status,temp,voltage,current,health,source,tech,cycles,eta,healthScore;
    BatteryRing ring;
    BatteryManager bm;
    Intent batteryIntent;
    int level=0, temperature=-1, millivolts=-1, microamps=Integer.MIN_VALUE, healthCode=1, plug=0, batteryStatus=1;
    ArrayList<Integer> history=new ArrayList<>();
    ArrayList<Long> sampleTimes=new ArrayList<>();
    ArrayList<Integer> sampleTemps=new ArrayList<>(), sampleCurrents=new ArrayList<>(), sampleVoltages=new ArrayList<>(), sampleStatuses=new ArrayList<>();
    int lastAlert=0;
    String page="Обзор";
    android.content.SharedPreferences prefs;
    final Handler sampleHandler=new Handler(Looper.getMainLooper());
    final Runnable sampleTask=new Runnable(){@Override public void run(){recordSample();sampleHandler.postDelayed(this,60000);}};

    BroadcastReceiver receiver=new BroadcastReceiver(){@Override public void onReceive(Context c,Intent i){batteryIntent=i;readBattery(i);}};
    @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(BG);getWindow().setNavigationBarColor(BG);getWindow().getDecorView().setSystemUiVisibility(0);bm=(BatteryManager)getSystemService(BATTERY_SERVICE);prefs=getSharedPreferences("battery42",MODE_PRIVATE);loadHistory();createNotificationChannel();if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{Manifest.permission.POST_NOTIFICATIONS},42);buildShell();batteryIntent=registerReceiver(receiver,new IntentFilter(Intent.ACTION_BATTERY_CHANGED));if(batteryIntent!=null)readBattery(batteryIntent);}
    int dp(float v){return (int)(v*getResources().getDisplayMetrics().density+.5f);}
    GradientDrawable shape(int color,int radius,int stroke){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(radius));if(stroke!=0)d.setStroke(dp(1),stroke);return d;}
    TextView label(String s,int size,int color,boolean bold){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(color);if(bold)t.setTypeface(null,1);return t;}
    LinearLayout column(){LinearLayout l=new LinearLayout(this);l.setOrientation(1);return l;}
    LinearLayout row(){LinearLayout l=new LinearLayout(this);l.setOrientation(0);l.setGravity(Gravity.CENTER_VERTICAL);return l;}
    LinearLayout panel(){LinearLayout p=column();p.setPadding(dp(17),dp(16),dp(17),dp(16));p.setBackground(shape(PANEL,22,0xff222b39));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.bottomMargin=dp(13);p.setLayoutParams(lp);return p;}
    void buildShell(){root=column();root.setBackgroundColor(BG);root.setPadding(dp(20),dp(18),dp(20),dp(8));root.setOnApplyWindowInsetsListener((v,insets)->{v.setPadding(dp(20),dp(18)+insets.getSystemWindowInsetTop(),dp(20),dp(8)+insets.getSystemWindowInsetBottom());return insets;});LinearLayout head=row();TextView brand=label("BATTERY",13,MUTED,true);TextView mark=label("  /  42",13,GREEN,true);head.addView(brand);head.addView(mark);head.addView(new View(this),new LinearLayout.LayoutParams(0,1,1));TextView live=label("● LIVE",11,GREEN,true);head.addView(live);root.addView(head);
        TextView heading=label("Энергия под контролем",25,TEXT,true);LinearLayout.LayoutParams hp=new LinearLayout.LayoutParams(-1,-2);hp.topMargin=dp(17);hp.bottomMargin=dp(4);root.addView(heading,hp);
        TextView sub=label("Мониторинг аккумулятора в реальном времени",12,MUTED,false);root.addView(sub);
        ScrollView scroll=new ScrollView(this);scroll.setFillViewport(false);content=column();content.setPadding(0,dp(18),0,dp(10));scroll.addView(content);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));
        nav=row();nav.setPadding(dp(5),dp(7),dp(5),dp(7));nav.setBackground(shape(PANEL,20,0xff222b39));String[] tabs={"Обзор","История","Состояние","Советы"};for(String s:tabs){TextView t=label(s,11,s.equals(page)?GREEN:MUTED,true);t.setGravity(Gravity.CENTER);t.setPadding(dp(7),dp(12),dp(7),dp(12));nav.addView(t,new LinearLayout.LayoutParams(0,-2,1));t.setOnClickListener(v->{page=s;buildPage();for(int j=0;j<nav.getChildCount();j++){TextView x=(TextView)nav.getChildAt(j);x.setTextColor(x.getText().toString().equals(page)?GREEN:MUTED);}});}root.addView(nav);setContentView(root);buildPage();}
    void buildPage(){content.removeAllViews();if(page.equals("Обзор"))overview();else if(page.equals("История"))historyPage();else if(page.equals("Состояние"))healthPage();else tipsPage();}
    void overview(){LinearLayout hero=panel();hero.setGravity(Gravity.CENTER_HORIZONTAL);TextView cap=label("ТЕКУЩИЙ ЗАРЯД",10,MUTED,true);hero.addView(cap);ring=new BatteryRing();LinearLayout.LayoutParams rp=new LinearLayout.LayoutParams(dp(180),dp(180));rp.topMargin=dp(7);hero.addView(ring,rp);pct=label(level+"%",39,TEXT,true);hero.addView(pct);status=label(statusText(),13,GREEN,true);LinearLayout.LayoutParams sp=new LinearLayout.LayoutParams(-2,-2);sp.topMargin=dp(5);hero.addView(status);eta=label(" ",12,MUTED,false);LinearLayout.LayoutParams ep=new LinearLayout.LayoutParams(-2,-2);ep.topMargin=dp(10);hero.addView(eta);content.addView(hero);
        TextView section=label("Показатели",17,TEXT,true);section.setPadding(dp(2),dp(5),0,dp(10));content.addView(section);
        LinearLayout r1=row();r1.addView(metric("Температура",tempText(), "°C"),new LinearLayout.LayoutParams(0,-2,1));r1.addView(metric("Напряжение",voltageText(),"V"),new LinearLayout.LayoutParams(0,-2,1));content.addView(r1);
        LinearLayout r2=row();r2.addView(metric("Ток",currentText(),"mA"),new LinearLayout.LayoutParams(0,-2,1));r2.addView(metric("Источник",sourceText(),"POWER"),new LinearLayout.LayoutParams(0,-2,1));content.addView(r2);
        LinearLayout p=panel();p.addView(label("ДИНАМИКА ЗАРЯДА",10,MUTED,true));TextView desc=label("Последние изменения уровня",12,MUTED,false);desc.setPadding(0,dp(5),0,dp(7));p.addView(desc);p.addView(new HistoryChart(),new LinearLayout.LayoutParams(-1,dp(115)));content.addView(p);
        LinearLayout insight=panel();insight.addView(label("СЕЙЧАС",10,GREEN,true));insight.addView(label(advice(),15,TEXT,true));insight.addView(label("Показания обновляются автоматически при изменении состояния батареи.",12,MUTED,false));content.addView(insight);
    }
    View metric(String name,String value,String unit){LinearLayout c=panel();c.setPadding(dp(14),dp(14),dp(12),dp(14));TextView n=label(name.toUpperCase(Locale.ROOT),10,MUTED,true);TextView v=label(value,21,TEXT,true);TextView u=label(unit,10,MUTED,false);c.addView(n);LinearLayout rr=row();rr.addView(v);rr.addView(u);rr.setGravity(Gravity.BOTTOM);c.addView(rr);return c;}
    void historyPage(){LinearLayout p=panel();p.addView(label("История заряда",21,TEXT,true));p.addView(label("Локальные измерения, сохранённые на этом телефоне",12,MUTED,false));p.addView(new HistoryChart(),new LinearLayout.LayoutParams(-1,dp(180)));content.addView(p);LinearLayout stats=panel();stats.addView(label("СОБРАНО ЗАПИСЕЙ",10,MUTED,true));stats.addView(label(String.valueOf(history.size()),28,TEXT,true));stats.addView(label("Замеры каждую минуту, пока приложение открыто. Последние 24 часа — до 1440 точек.",12,MUTED,false));content.addView(stats);
        LinearLayout analytics=panel();analytics.addView(label("АНАЛИТИКА ЗАРЯДКИ",16,TEXT,true));analytics.addView(infoLine("Зарядных сессий",String.valueOf(chargeSessions())));analytics.addView(infoLine("Средняя температура",averageTemp()));analytics.addView(infoLine("Скорость последней зарядки",chargingRate()));analytics.addView(infoLine("Последний замер",lastSampleTime()));content.addView(analytics);
        LinearLayout thermal=panel();thermal.addView(label("ТЕМПЕРАТУРА",14,TEXT,true));thermal.addView(new TemperatureChart(),new LinearLayout.LayoutParams(-1,dp(110)));content.addView(thermal);
        TextView export=label("Поделиться историей",14,BLUE,true);export.setPadding(dp(5),dp(12),0,dp(12));export.setOnClickListener(v->shareHistory());content.addView(export);TextView clear=label("Очистить историю",14,RED,true);clear.setPadding(dp(5),dp(12),0,dp(12));clear.setOnClickListener(v->{history.clear();sampleTimes.clear();sampleTemps.clear();sampleCurrents.clear();sampleVoltages.clear();sampleStatuses.clear();saveHistory();buildPage();});content.addView(clear);}
    void healthPage(){LinearLayout p=panel();p.addView(label("Состояние аккумулятора",21,TEXT,true));p.addView(label(healthText(),17,GREEN,true));p.addView(label("Android сообщает системный статус батареи. Это не лабораторная диагностика ёмкости.",12,MUTED,false));content.addView(p);LinearLayout grid=panel();grid.addView(infoLine("Системное здоровье",healthText()));grid.addView(infoLine("Температура",tempText()));grid.addView(infoLine("Технология",techText()));grid.addView(infoLine("Циклы зарядки",cycleText()));grid.addView(infoLine("Оценка износа","Недоступна без проектной ёмкости"));content.addView(grid);LinearLayout note=panel();note.addView(label("Почему нет процента износа?",16,TEXT,true));note.addView(label("Стандартный Android API не гарантирует доступ к заводской ёмкости батареи. Поэтому приложение не подменяет реальное измерение случайным процентом. На некоторых моделях доступны дополнительные данные производителя.",12,MUTED,false));content.addView(note);}
    View infoLine(String a,String b){LinearLayout r=row();TextView x=label(a,13,MUTED,false);TextView y=label(b,13,TEXT,true);r.addView(x,new LinearLayout.LayoutParams(0,-2,1));r.addView(y);View line=new View(this);line.setBackgroundColor(0xff293342);LinearLayout wrap=column();wrap.addView(r);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,dp(1));lp.topMargin=dp(12);lp.bottomMargin=dp(12);wrap.addView(line,lp);return wrap;}
    void tipsPage(){LinearLayout p=panel();p.addView(label("Умные рекомендации",21,TEXT,true));String advice=advice();p.addView(label(advice,15,GREEN,true));p.addView(label("• Избегай длительного нагрева телефона.\n\n• Не оставляй устройство под прямым солнцем во время зарядки.\n\n• Используй качественный адаптер и кабель.\n\n• Если корпус заметно нагревается, дай телефону остыть.",13,MUTED,false));content.addView(p);LinearLayout n=panel();n.addView(label("Пороговые уведомления",16,TEXT,true));n.addView(label("В этой версии доступны визуальные предупреждения о высокой температуре и низком заряде. Фоновый контроль и системные уведомления добавим отдельным этапом, чтобы корректно запросить разрешения Android.",12,MUTED,false));content.addView(n);}
    String statusText(){return batteryStatus==5?"Полностью заряжен":batteryStatus==2?"Идёт зарядка":batteryStatus==3?"Работает от батареи":"Ожидание";}
    String tempText(){return temperature<0?"Нет данных":String.format(Locale.getDefault(),"%.1f",temperature/10f);}
    String voltageText(){return millivolts<=0?"—":String.format(Locale.getDefault(),"%.2f",millivolts/1000f);}
    String currentText(){return microamps==Integer.MIN_VALUE?"—":String.format(Locale.getDefault(),"%+.0f",microamps/1000f);}
    String sourceText(){return plug==1?"Сеть":plug==2?"USB":plug==4?"Беспроводная":plug==8?"Док":"Нет";}
    String healthText(){switch(healthCode){case 2:return "Хорошее";case 3:return "Перегрев";case 4:return "Неисправность";case 5:return "Перенапряжение";case 7:return "Переохлаждение";default:return "Нет данных";}}
    String techText(){String s=batteryIntent==null?null:batteryIntent.getStringExtra(BatteryManager.EXTRA_TECHNOLOGY);return s==null||s.isEmpty()?"Неизвестно":s;}
    String cycleText(){if(Build.VERSION.SDK_INT>=34&&batteryIntent!=null){int c=batteryIntent.getIntExtra("android.os.extra.CYCLE_COUNT",-1);return c>=0?String.valueOf(c):"Нет данных";}return "Требуется Android 14+";}
    String advice(){if(temperature>=450)return "Высокая температура. Отключи зарядку и дай устройству остыть.";if(level<=15)return "Низкий заряд. Пора подключить зарядное устройство.";if(batteryStatus==2&&temperature>=400)return "Во время зарядки батарея заметно нагрелась.";if(batteryStatus==5)return "Заряд 100%. Можно отключить питание.";return "Показатели в обычном диапазоне. Продолжай наблюдение.";}
    void readBattery(Intent i){int oldLevel=level,oldStatus=batteryStatus,oldPlug=plug,oldTemp=temperature;int lev=i.getIntExtra(BatteryManager.EXTRA_LEVEL,-1),sc=i.getIntExtra(BatteryManager.EXTRA_SCALE,100);if(lev>=0&&sc>0)level=Math.round(lev*100f/sc);temperature=i.getIntExtra(BatteryManager.EXTRA_TEMPERATURE,-1);millivolts=i.getIntExtra(BatteryManager.EXTRA_VOLTAGE,-1);healthCode=i.getIntExtra(BatteryManager.EXTRA_HEALTH,1);plug=i.getIntExtra(BatteryManager.EXTRA_PLUGGED,0);batteryStatus=i.getIntExtra(BatteryManager.EXTRA_STATUS,1);microamps=bm.getIntProperty(BatteryManager.BATTERY_PROPERTY_CURRENT_NOW);if(history.isEmpty()||oldLevel!=level||oldStatus!=batteryStatus||oldPlug!=plug||(oldTemp>=0&&Math.abs(oldTemp-temperature)>=10)){recordSample();}checkAlerts();if(pct!=null){pct.setText(level+"%");status.setText(statusText());ring.invalidate();}if(eta!=null){long ms=Build.VERSION.SDK_INT>=28?bm.computeChargeTimeRemaining():-1;eta.setText(ms>0&&batteryStatus==2?"До полного заряда примерно "+formatTime(ms):" ");}if(page.equals("Обзор"))buildPage();}
    String formatTime(long ms){long m=ms/60000;return (m/60)+" ч "+(m%60)+" мин";}
    void recordSample(){if(batteryIntent!=null){long now=System.currentTimeMillis();if(!sampleTimes.isEmpty()&&now-sampleTimes.get(sampleTimes.size()-1)<15000&&history.get(history.size()-1)==level&&sampleStatuses.get(sampleStatuses.size()-1)==batteryStatus)return;history.add(level);sampleTimes.add(now);sampleTemps.add(temperature);sampleCurrents.add(microamps);sampleVoltages.add(millivolts);sampleStatuses.add(batteryStatus);while(history.size()>1440){history.remove(0);sampleTimes.remove(0);sampleTemps.remove(0);sampleCurrents.remove(0);sampleVoltages.remove(0);sampleStatuses.remove(0);}saveHistory();if(page.equals("Обзор")||page.equals("История"))buildPage();}}
    @Override protected void onResume(){super.onResume();sampleHandler.removeCallbacks(sampleTask);sampleHandler.postDelayed(sampleTask,60000);}
    @Override protected void onPause(){sampleHandler.removeCallbacks(sampleTask);super.onPause();}
    void loadHistory(){String v2=prefs.getString("history_v2","");if(!v2.isEmpty()){try{for(String entry:v2.split(";")){String[] a=entry.split(":");if(a.length==6){sampleTimes.add(Long.parseLong(a[0]));history.add(Integer.parseInt(a[1]));sampleTemps.add(Integer.parseInt(a[2]));sampleCurrents.add(Integer.parseInt(a[3]));sampleVoltages.add(Integer.parseInt(a[4]));sampleStatuses.add(Integer.parseInt(a[5]));}}}catch(Exception e){history.clear();sampleTimes.clear();sampleTemps.clear();sampleCurrents.clear();sampleVoltages.clear();sampleStatuses.clear();}}else{String s=prefs.getString("history","");if(!s.isEmpty())try{for(String x:s.split(",")){history.add(Integer.parseInt(x));sampleTimes.add(System.currentTimeMillis());sampleTemps.add(-1);sampleCurrents.add(Integer.MIN_VALUE);sampleVoltages.add(-1);sampleStatuses.add(1);}}catch(Exception e){history.clear();}}}
    void saveHistory(){StringBuilder b=new StringBuilder();for(int i=0;i<history.size();i++){if(b.length()>0)b.append(";");b.append(sampleTimes.get(i)).append(":").append(history.get(i)).append(":").append(sampleTemps.get(i)).append(":").append(sampleCurrents.get(i)).append(":").append(sampleVoltages.get(i)).append(":").append(sampleStatuses.get(i));}prefs.edit().putString("history_v2",b.toString()).putString("history",history.toString()).apply();}
    int chargeSessions(){int n=0;boolean charging=false;for(int s:sampleStatuses){boolean now=s==2||s==5;if(now&&!charging)n++;charging=now;}return n;}
    String averageTemp(){int sum=0,n=0;for(int t:sampleTemps)if(t>=0){sum+=t;n++;}return n==0?"Нет данных":String.format(Locale.getDefault(),"%.1f °C",sum/(float)n/10f);}
    String chargingRate(){int first=-1,last=-1;for(int i=0;i<history.size();i++)if(sampleStatuses.get(i)==2){if(first<0)first=i;last=i;}if(first<0||last<=first)return "Собираем данные";long mins=(sampleTimes.get(last)-sampleTimes.get(first))/60000;if(mins<1)return "Собираем данные";float rate=(history.get(last)-history.get(first))*60f/mins;return String.format(Locale.getDefault(),"%+.1f%%/ч",rate);}
    String lastSampleTime(){if(sampleTimes.isEmpty())return "Нет данных";return new SimpleDateFormat("HH:mm:ss",Locale.getDefault()).format(new Date(sampleTimes.get(sampleTimes.size()-1)));}
    void shareHistory(){StringBuilder b=new StringBuilder("Battery Monitor 42 — история\n");for(int i=0;i<history.size();i++)b.append(new SimpleDateFormat("dd.MM HH:mm",Locale.getDefault()).format(new Date(sampleTimes.get(i)))).append(" | ").append(history.get(i)).append("% | ").append(sampleTemps.get(i)<0?"—":sampleTemps.get(i)/10f+" °C").append("\n");Intent send=new Intent(Intent.ACTION_SEND);send.setType("text/plain");send.putExtra(Intent.EXTRA_TEXT,b.toString());startActivity(Intent.createChooser(send,"Экспорт истории"));}
    void createNotificationChannel(){if(Build.VERSION.SDK_INT>=26){NotificationChannel ch=new NotificationChannel("battery42_alerts","Состояние аккумулятора",NotificationManager.IMPORTANCE_DEFAULT);ch.setDescription("Предупреждения о температуре и уровне заряда");((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).createNotificationChannel(ch);}}
    void checkAlerts(){int alert=temperature>=450?2:level<=10?1:(batteryStatus==5?3:0);if(alert==0){lastAlert=0;prefs.edit().putInt("last_alert",0).apply();return;}if(alert==lastAlert)return;lastAlert=alert;prefs.edit().putInt("last_alert",alert).apply();if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)return;String title=alert==2?"Перегрев аккумулятора":alert==1?"Низкий заряд":"Зарядка завершена";String body=alert==2?"Температура "+tempText()+" °C. Отключи зарядку и дай телефону остыть.":alert==1?"Осталось "+level+"% заряда. Подключи зарядное устройство.":"Аккумулятор заряжен до 100%.";Notification.Builder nb=Build.VERSION.SDK_INT>=26?new Notification.Builder(this,"battery42_alerts"):new Notification.Builder(this);nb.setSmallIcon(android.R.drawable.ic_lock_idle_charging).setContentTitle(title).setContentText(body).setAutoCancel(true);((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).notify(42,nb.build());}
    class TemperatureChart extends View{Paint p=new Paint(3);TemperatureChart(){super(MainActivity.this);}protected void onDraw(Canvas c){float w=getWidth(),h=getHeight(),l=dp(8),r=w-dp(8),t=dp(8),b=h-dp(8);p.setColor(0xff293342);p.setStrokeWidth(dp(1));for(int j=0;j<3;j++){float y=t+(b-t)*j/2f;c.drawLine(l,y,r,y,p);}int count=0;for(int x:sampleTemps)if(x>=0)count++;if(count<2){p.setColor(MUTED);p.setTextSize(dp(11));c.drawText("Собираем данные о температуре…",l,b-dp(5),p);return;}p.setColor(ORANGE);p.setStrokeWidth(dp(2.5f));p.setStyle(Paint.Style.STROKE);Path path=new Path();int seen=0;for(int i=0;i<sampleTemps.size();i++){int v=sampleTemps.get(i);if(v<0)continue;float x=l+(r-l)*seen/(float)(count-1),y=b-(b-t)*Math.max(0,Math.min(600,v))/600f;if(seen++==0)path.moveTo(x,y);else path.lineTo(x,y);}c.drawPath(path,p);p.setStyle(Paint.Style.FILL);}}
    @Override protected void onDestroy(){try{unregisterReceiver(receiver);}catch(Exception ignored){}super.onDestroy();}
    class BatteryRing extends View{Paint p=new Paint(3);BatteryRing(){super(MainActivity.this);}protected void onDraw(Canvas c){float d=Math.min(getWidth(),getHeight()),cx=getWidth()/2f,cy=getHeight()/2f,r=d*.39f;p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(dp(11));p.setStrokeCap(Paint.Cap.ROUND);p.setColor(0xff283241);c.drawArc(cx-r,cy-r,cx+r,cy+r,-90,360,false,p);p.setColor(level<=15?RED:GREEN);c.drawArc(cx-r,cy-r,cx+r,cy+r,-90,level*3.6f,false,p);p.setStyle(Paint.Style.FILL);p.setColor(0xff202a37);c.drawCircle(cx,cy,dp(5),p);}}
    class HistoryChart extends View{Paint p=new Paint(3);HistoryChart(){super(MainActivity.this);}protected void onDraw(Canvas c){float w=getWidth(),h=getHeight(),left=dp(8),right=w-dp(8),top=dp(10),bottom=h-dp(20);p.setStrokeWidth(dp(1));p.setColor(0xff293342);for(int j=0;j<4;j++){float y=top+(bottom-top)*j/3f;c.drawLine(left,y,right,y,p);}if(history.size()<2){p.setColor(MUTED);p.setTextSize(dp(11));c.drawText("Собираем данные…",left,bottom-dp(8),p);return;}p.setColor(GREEN);p.setStrokeWidth(dp(2.5f));p.setStyle(Paint.Style.STROKE);Path path=new Path();for(int i=0;i<history.size();i++){float x=left+(right-left)*i/(float)(history.size()-1),y=bottom-(bottom-top)*history.get(i)/100f;if(i==0)path.moveTo(x,y);else path.lineTo(x,y);}c.drawPath(path,p);p.setStyle(Paint.Style.FILL);p.setColor(GREEN);float x=right,y=bottom-(bottom-top)*history.get(history.size()-1)/100f;c.drawCircle(x,y,dp(4),p);}}
}